-- Reading lists are visible only to their owner and accepted friends.
do $$
begin
  if to_regclass('public.friend_reading_lists') is not null then
    alter table public.friend_reading_lists enable row level security;
    revoke all on public.friend_reading_lists from anon, authenticated;
    grant select, insert, update, delete on public.friend_reading_lists to authenticated;
    execute 'create policy "Owners and accepted friends read lists" on public.friend_reading_lists for select to authenticated using (owner_id = (select auth.jwt() ->> ''sub'') or exists (select 1 from public.friendships f where f.status = ''accepted'' and ((f.user_id = owner_id and f.friend_id = (select auth.jwt() ->> ''sub'')) or (f.friend_id = owner_id and f.user_id = (select auth.jwt() ->> ''sub'')))))';
    execute 'create policy "Owners insert reading lists" on public.friend_reading_lists for insert to authenticated with check (owner_id = (select auth.jwt() ->> ''sub''))';
    execute 'create policy "Owners update reading lists" on public.friend_reading_lists for update to authenticated using (owner_id = (select auth.jwt() ->> ''sub'')) with check (owner_id = (select auth.jwt() ->> ''sub''))';
    execute 'create policy "Owners delete reading lists" on public.friend_reading_lists for delete to authenticated using (owner_id = (select auth.jwt() ->> ''sub''))';
  end if;
end $$;

-- Community books are public to read, but only their author may change or remove them.
do $$
begin
  if to_regclass('public.community_books') is not null then
    -- The app writes the Clerk account id into owner_id. Some earlier project
    -- versions created this table without that column.
    alter table public.community_books add column if not exists owner_id text;
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'community_books' and column_name = 'user_id'
    ) then
      execute 'update public.community_books set owner_id = user_id::text where owner_id is null';
    elsif exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'community_books' and column_name = 'created_by'
    ) then
      execute 'update public.community_books set owner_id = created_by::text where owner_id is null';
    end if;
    alter table public.community_books enable row level security;
    revoke all on public.community_books from anon, authenticated;
    grant select on public.community_books to anon, authenticated;
    grant insert, update, delete on public.community_books to authenticated;
    execute 'drop policy if exists "Public can read community books" on public.community_books';
    execute 'drop policy if exists "Authors manage their community books" on public.community_books';
    execute 'create policy "Public can read community books" on public.community_books for select to anon, authenticated using (true)';
    execute 'create policy "Authors manage their community books" on public.community_books for all to authenticated using (owner_id = (select auth.jwt() ->> ''sub'')) with check (owner_id = (select auth.jwt() ->> ''sub''))';
  end if;
end $$;

-- Account data cleanup is explicit and scoped to the authenticated Clerk subject.
create or replace function public.delete_my_library_data()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare current_id text := auth.jwt() ->> 'sub';
begin
  if current_id is null then raise exception 'Authentication required'; end if;
  delete from public.chat_messages where sender_id = current_id or receiver_id = current_id;
  delete from public.friendships where user_id = current_id or friend_id = current_id;
  delete from public.book_likes where user_id = current_id;
  delete from public.reader_stats where id = current_id;
  if to_regclass('public.reader_state') is not null then
    execute 'delete from public.reader_state where owner_id = $1' using current_id;
    execute 'delete from public.reader_note_history where owner_id = $1' using current_id;
  end if;
  delete from public.user_profiles where user_id = current_id;
  if to_regclass('public.friend_reading_lists') is not null then
    execute 'delete from public.friend_reading_lists where owner_id = $1' using current_id;
  end if;
  if to_regclass('public.community_books') is not null then
    execute 'delete from public.community_books where owner_id = $1' using current_id;
  end if;
  if to_regclass('public.content_reports') is not null then
    execute 'delete from public.content_reports where reporter_id = $1' using current_id;
  end if;
end;
$$;
revoke all on function public.delete_my_library_data() from public, anon;
grant execute on function public.delete_my_library_data() to authenticated;



-- SOURCE: supabase-book-illustrations.sql
-- Apply in the Supabase SQL Editor to enable images inside user-created books.
-- Public read lets every reader see an illustration; uploads and edits are
-- restricted to the authenticated Clerk user whose id is the first path part.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'book-illustrations',
  'book-illustrations',
  true,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
set public = true,
    file_size_limit = 5242880,
    allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

drop policy if exists "Anyone can read book illustrations" on storage.objects;
drop policy if exists "Authors can upload book illustrations" on storage.objects;
drop policy if exists "Authors can update book illustrations" on storage.objects;
drop policy if exists "Authors can delete book illustrations" on storage.objects;

create policy "Anyone can read book illustrations"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'book-illustrations');

create policy "Authors can upload book illustrations"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  );

create policy "Authors can update book illustrations"
  on storage.objects for update to authenticated
  using (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  )
  with check (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  );

create policy "Authors can delete book illustrations"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  );


-- SOURCE: supabase-content-reports.sql
-- Apply in Supabase SQL Editor. Reports are submitted by signed-in readers;
-- review and resolution happen from the Supabase dashboard with an admin role.
create table if not exists public.content_reports (
  id bigint generated by default as identity primary key,
  reporter_id text not null,
  content_type text not null check (content_type in ('book')),
  content_id text not null,
  content_title text not null,
  reason text not null check (char_length(trim(reason)) between 1 and 1000),
  status text not null default 'open' check (status in ('open', 'reviewing', 'resolved', 'dismissed')),
  created_at timestamptz not null default now(),
  reviewed_at timestamptz,
  reviewer_note text
);

create index if not exists content_reports_open_created_idx
  on public.content_reports (created_at desc) where status = 'open';
create index if not exists content_reports_content_idx
  on public.content_reports (content_type, content_id, created_at desc);

alter table public.content_reports enable row level security;
revoke all on public.content_reports from anon, authenticated;
grant insert on public.content_reports to authenticated;
grant usage on sequence public.content_reports_id_seq to authenticated;
drop policy if exists "Signed-in readers can report content" on public.content_reports;
create policy "Signed-in readers can report content"
  on public.content_reports for insert to authenticated
  with check (
    reporter_id = (select auth.jwt() ->> 'sub')
    and char_length(trim(reason)) between 1 and 1000
    and content_type = 'book'
  );

-- No client read/update policy is granted: report details remain private to
-- database administrators and cannot be enumerated or resolved by reporters.


-- SOURCE: supabase-private-chat.sql
-- Apply with the matching client: attachments store paths, never signed URLs.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('chat-photos', 'chat-photos', false, 5242880, array['image/jpeg','image/png','image/webp','image/gif'])
on conflict (id) do update set public = false, file_size_limit = 5242880,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "Public can read chat photos" on storage.objects;
drop policy if exists "Chat participants read photos" on storage.objects;
drop policy if exists "Users upload their own chat photos" on storage.objects;
drop policy if exists "Users update their own chat photos" on storage.objects;

-- New paths: sender/receiver/random-file. Existing sender/file attachments are
-- readable to their sender and the recipients of existing messages only.
create policy "Chat participants read photos" on storage.objects for select to authenticated
using (bucket_id = 'chat-photos' and (
  (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  or (storage.foldername(name))[2] = (select auth.jwt() ->> 'sub')
  or exists (select 1 from public.chat_messages m
    where m.receiver_id = (select auth.jwt() ->> 'sub')
      and (m.attachment_url = 'chat-photos/' || name
        or split_part(m.attachment_url, '/storage/v1/object/public/chat-photos/', 2) = name
        or split_part(m.body, '/storage/v1/object/public/chat-photos/', 2) = name))
));
create policy "Users upload their own chat photos" on storage.objects for insert to authenticated
with check (bucket_id = 'chat-photos'
  and (storage.foldername(name))[1] = (select auth.jwt() ->> 'sub')
  and array_length(storage.foldername(name), 1) = 2
  and exists (select 1 from public.friendships f where f.user_id = (select auth.jwt() ->> 'sub')
    and f.friend_id = (storage.foldername(name))[2] and f.status = 'accepted'));

-- Prevent a sender from borrowing another user's file path to grant themselves
-- access through a forged message. Existing attachments survive text edits.
create or replace function public.validate_chat_attachment()
returns trigger language plpgsql set search_path = '' as $$
begin
  if TG_OP = 'UPDATE' and new.attachment_url is not distinct from old.attachment_url
    and new.body is not distinct from old.body then return new; end if;
  if TG_OP = 'UPDATE' and new.attachment_url is not distinct from old.attachment_url
    and new.body not like '%/storage/v1/object/%' then return new; end if;
  if new.attachment_url is not null and not starts_with(new.attachment_url,
    'chat-photos/' || new.sender_id || '/' || new.receiver_id || '/') then
    raise exception 'Invalid attachment path';
  end if;
  if new.body like '%/storage/v1/object/%' then
    raise exception 'Use a private attachment instead of a storage URL';
  end if;
  return new;
end $$;
drop trigger if exists validate_chat_attachment on public.chat_messages;
create trigger validate_chat_attachment before insert or update on public.chat_messages
for each row execute function public.validate_chat_attachment();


-- SOURCE: supabase-reader-state.sql
-- Private, per-item reading state; unrelated books and notes cannot overwrite each other.
create table if not exists public.reader_state (
  owner_id text not null,
  kind text not null check (kind in ('progress','bookmark','note')),
  item_key text not null check (length(item_key) between 1 and 100),
  revision text collate "C" not null check (revision ~ '^[0-9]{13}-[a-zA-Z0-9-]{1,40}$'),
  value jsonb not null check (octet_length(value::text) <= 20000),
  primary key (owner_id, kind, item_key)
);
create table if not exists public.reader_note_history (
  owner_id text not null, item_key text not null,
  revision text collate "C" not null, value jsonb not null,
  saved_at timestamptz not null default now(),
  primary key (owner_id, item_key, revision)
);
alter table public.reader_state enable row level security;
alter table public.reader_note_history enable row level security;
revoke all on public.reader_state, public.reader_note_history from anon, authenticated;
grant select on public.reader_state, public.reader_note_history to authenticated;
drop policy if exists "Own reading state" on public.reader_state;
create policy "Own reading state" on public.reader_state for select to authenticated
using (owner_id = (select auth.jwt() ->> 'sub'));
drop policy if exists "Own note history" on public.reader_note_history;
create policy "Own note history" on public.reader_note_history for select to authenticated
using (owner_id = (select auth.jwt() ->> 'sub'));

create or replace function public.save_reader_state(entries jsonb)
returns void language plpgsql security definer set search_path = '' as $$
declare owner text := auth.jwt() ->> 'sub'; entry jsonb; k text; v jsonb;
begin
  if owner is null then raise exception 'Authentication required'; end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries) > 100 then
    raise exception 'Invalid batch';
  end if;
  for entry in select * from jsonb_array_elements(entries) loop
    k := entry ->> 'kind'; v := entry -> 'value';
    if k = 'note' then
      if jsonb_typeof(v) <> 'string' or length(v #>> '{}') > 4000 then raise exception 'Invalid note'; end if;
    elsif k in ('progress','bookmark') then
      if coalesce(jsonb_typeof(v) <> 'object', true) or coalesce(jsonb_typeof(v -> 'title') <> 'string', true)
        or not coalesce((v ->> 'page') ~ '^[1-9][0-9]{0,7}$', false)
        or coalesce(v ? 'offset' and not coalesce((v ->> 'offset') ~ '^[0-9]{1,9}$', false), false) then raise exception 'Invalid position'; end if;
    else raise exception 'Invalid kind'; end if;
    insert into public.reader_state(owner_id,kind,item_key,revision,value)
      values(owner,k,entry->>'item_key',entry->>'revision',v)
    on conflict(owner_id,kind,item_key) do update set revision=excluded.revision,value=excluded.value
      where excluded.revision > public.reader_state.revision;
    -- Retain even an older offline note that loses a concurrent update.
    if k = 'note' then
      insert into public.reader_note_history(owner_id,item_key,revision,value)
        values(owner,entry->>'item_key',entry->>'revision',v) on conflict do nothing;
    end if;
  end loop;
end $$;
revoke all on function public.save_reader_state(jsonb) from public, anon;
grant execute on function public.save_reader_state(jsonb) to authenticated;

-- Cleanup runs in the same transaction as account-data deletion.
create or replace function public.delete_reader_state_for_profile()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  delete from public.reader_state where owner_id=old.user_id;
  delete from public.reader_note_history where owner_id=old.user_id;
  return old;
end $$;
drop trigger if exists delete_reader_state_for_profile on public.user_profiles;
create trigger delete_reader_state_for_profile after delete on public.user_profiles
for each row execute function public.delete_reader_state_for_profile();


-- SOURCE: supabase-reader-rewards.sql
-- Server-owned XP and an idempotent reward ledger for authenticated readers.
create table if not exists public.reader_xp_ledger (
  owner_id text not null,
  reward_key text not null check (length(reward_key) between 1 and 160),
  xp_delta integer not null check (xp_delta between 0 and 100000),
  pages_delta integer not null default 0 check (pages_delta between 0 and 200),
  created_at timestamptz not null default now(),
  primary key (owner_id, reward_key)
);
create index if not exists reader_xp_ledger_daily_idx
  on public.reader_xp_ledger(owner_id, created_at desc) where reward_key like 'read:%';
alter table public.reader_xp_ledger enable row level security;
revoke all on public.reader_xp_ledger from public, anon, authenticated;

alter table public.reader_stats add column if not exists last_read_date date;

-- Keep profile fields editable, while XP, level, streak and reading totals can
-- only be written by the SECURITY DEFINER award functions below.
revoke insert, update on public.reader_stats from authenticated;
grant select on public.reader_stats to anon, authenticated;
grant insert (id, nickname, avatar, books_published, updated_at) on public.reader_stats to authenticated;
grant update (nickname, avatar, books_published, updated_at) on public.reader_stats to authenticated;

create or replace function public.apply_reader_reward(p_owner_id text, p_reward_key text, p_xp integer, p_pages integer)
returns boolean
language plpgsql security definer set search_path = '' as $$
declare inserted_key text; daily_xp integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id, 42));
  select coalesce(sum(xp_delta), 0) into daily_xp from public.reader_xp_ledger
    where owner_id = p_owner_id and created_at >= date_trunc('day', now());
  if daily_xp + p_xp > 1500 then return false; end if;
  insert into public.reader_stats(id) values (p_owner_id) on conflict (id) do nothing;
  insert into public.reader_xp_ledger(owner_id, reward_key, xp_delta, pages_delta)
    values (p_owner_id, p_reward_key, p_xp, p_pages)
    on conflict (owner_id, reward_key) do nothing
    returning reward_key into inserted_key;
  if inserted_key is null then return false; end if;

  update public.reader_stats set
    xp = xp + p_xp,
    level = 1,
    pages_read = pages_read + p_pages,
    last_read_date = case when p_pages > 0 then current_date else last_read_date end,
    updated_at = now()
    where id = p_owner_id;
  update public.reader_stats set level = floor((sqrt(1 + 0.08 * xp) - 1) / 2)::integer + 1 where id = p_owner_id;
  return true;
end $$;
revoke all on function public.apply_reader_reward(text, text, integer, integer) from public, anon, authenticated;

create or replace function public.award_reading_pages(p_book_id bigint, p_page_indexes integer[])
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare current_id text := auth.jwt() ->> 'sub'; page_index integer; added integer := 0;
  day_count integer; expected_pages integer; result_row public.reader_stats%rowtype;
begin
  if current_id is null then raise exception 'Authentication required'; end if;
  if p_book_id is null or p_book_id <= 0 or p_page_indexes is null
    or cardinality(p_page_indexes) > 20 then raise exception 'Invalid reading activity'; end if;
  if exists (select 1 from unnest(p_page_indexes) as p(i) where i is null or i < 0 or i > 9999999) then
    raise exception 'Invalid page index';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(current_id, 42));
  select jsonb_array_length(pages) into expected_pages from public.community_books where id = p_book_id;
  if expected_pages is not null and exists (select 1 from unnest(p_page_indexes) as p(i) where i >= expected_pages) then
    raise exception 'Page index is outside the book';
  end if;

  for page_index in select distinct i from unnest(p_page_indexes) as p(i) order by i loop
    select count(*) into day_count from public.reader_xp_ledger
      where owner_id = current_id and reward_key like 'read:%' and created_at >= date_trunc('day', now());
    exit when day_count >= 100;
    if public.apply_reader_reward(current_id, 'read:' || p_book_id::text || ':' || page_index::text, 15, 1) then
      added := added + 1;
    end if;
  end loop;

  select * into result_row from public.reader_stats where id = current_id;
  return jsonb_build_object('xp', result_row.xp, 'level', result_row.level,
    'streakDays', result_row.streak_days, 'pagesRead', result_row.pages_read,
    'gainedXp', added * 15, 'awardedPages', added);
end $$;
revoke all on function public.award_reading_pages(bigint, integer[]) from public, anon;
grant execute on function public.award_reading_pages(bigint, integer[]) to authenticated;

-- Publication reward runs only on a new row insert. Retrying an upsert or
-- editing a published book cannot create a second publication reward.
create or replace function public.reward_new_book_publication()
returns trigger language plpgsql security definer set search_path = '' as $$
declare safe_pages integer := greatest(1, least(coalesce(jsonb_array_length(new.pages), 1), 200));
begin
  perform public.apply_reader_reward(new.owner_id, 'publish:' || new.id::text, least(40 + safe_pages * 15, 1000), 0);
  return new;
end $$;
drop trigger if exists reward_new_book_publication on public.community_books;
create trigger reward_new_book_publication after insert on public.community_books
  for each row when (new.owner_id is not null and new.is_user_book)
  execute function public.reward_new_book_publication();

create or replace function public.delete_reader_xp_ledger_for_profile()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  delete from public.reader_xp_ledger where owner_id = old.id;
  return old;
end $$;
drop trigger if exists delete_reader_xp_ledger_for_profile on public.reader_stats;
create trigger delete_reader_xp_ledger_for_profile after delete on public.reader_stats
  for each row execute function public.delete_reader_xp_ledger_for_profile();


-- SOURCE: supabase-reader-journey.sql

create or replace function public.apply_reader_reward(p_owner_id text, p_reward_key text, p_xp integer, p_pages integer)
returns boolean
language plpgsql security definer set search_path = '' as $$
declare inserted_key text; daily_xp integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id, 42));
  select coalesce(sum(xp_delta), 0) into daily_xp from public.reader_xp_ledger
    where owner_id = p_owner_id and created_at >= date_trunc('day', now());
  if daily_xp + p_xp > 1500 then return false; end if;
  insert into public.reader_stats(id) values (p_owner_id) on conflict (id) do nothing;
  insert into public.reader_xp_ledger(owner_id, reward_key, xp_delta, pages_delta)
    values (p_owner_id, p_reward_key, p_xp, p_pages)
    on conflict (owner_id, reward_key) do nothing
    returning reward_key into inserted_key;
  if inserted_key is null then return false; end if;

  update public.reader_stats set
    xp = xp + p_xp,
    level = 1,
    pages_read = pages_read + p_pages,
    last_read_date = case when p_pages > 0 then current_date else last_read_date end,
    updated_at = now()
    where id = p_owner_id;
  update public.reader_stats set level = floor((sqrt(1 + 0.08 * xp) - 1) / 2)::integer + 1 where id = p_owner_id;
  return true;
end $$;
revoke all on function public.apply_reader_reward(text, text, integer, integer) from public, anon, authenticated;

-- Daily site visits and achievements. Rewards remain server-owned and idempotent.
alter table public.reader_stats add column if not exists last_visit_date date;
alter table public.reader_stats add column if not exists visit_timezone text;
update public.reader_stats set last_visit_date = last_read_date where last_visit_date is null and last_read_date is not null;

create or replace function public.reader_journey(p_claim text default null, p_timezone text default 'UTC')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  uid text := auth.jwt() ->> 'sub'; zone text; today date; before_xp integer;
  r public.reader_stats%rowtype; item record; progress integer; key text; earned boolean;
  daily_pages integer; books_started integer; achievements jsonb := '[]'::jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(uid, 42));
  insert into public.reader_stats(id) values(uid) on conflict(id) do nothing;
  select * into r from public.reader_stats where id = uid;
  before_xp := r.xp;
  zone := r.visit_timezone;
  if zone is null then
    select name into zone from pg_timezone_names where name = p_timezone;
    zone := coalesce(zone, 'UTC');
    update public.reader_stats set visit_timezone = zone where id = uid;
  end if;
  today := (now() at time zone zone)::date;
  if r.last_visit_date is distinct from today then
    update public.reader_stats set
      streak_days = case when last_visit_date = today - 1 then streak_days + 1 else 1 end,
      last_visit_date = today, updated_at = now() where id = uid;
  end if;
  perform public.apply_reader_reward(uid, 'visit:' || today::text, 10, 0);
  select * into r from public.reader_stats where id = uid;
  select coalesce(sum(pages_delta),0) into daily_pages from public.reader_xp_ledger
    where owner_id = uid and (created_at at time zone zone)::date = today and reward_key like 'read:%';
  select count(distinct split_part(reward_key, ':', 2)) into books_started
    from public.reader_xp_ledger where owner_id = uid and reward_key like 'read:%';
  for item in select * from (values
    ('first10', 'Первые шаги', 'Прочитайте 10 новых страниц', 'pages', 10, 50),
    ('pages100', 'За главой — глава', 'Прочитайте 100 новых страниц', 'pages', 100, 150),
    ('pages500', 'Книжный исследователь', 'Прочитайте 500 новых страниц', 'pages', 500, 300),
    ('visits3', 'Хорошее начало', 'Заходите на сайт 3 дня подряд', 'streak', 3, 40),
    ('visits7', 'Неделя с книгой', 'Заходите на сайт 7 дней подряд', 'streak', 7, 100),
    ('visits30', 'Литературная привычка', 'Заходите на сайт 30 дней подряд', 'streak', 30, 400),
    ('pages1000', 'Хранитель библиотеки', 'Прочитайте 1000 новых страниц', 'pages', 1000, 500),
    ('books3', 'Разведчик миров', 'Прочитайте хотя бы одну новую страницу в 3 разных книгах', 'books', 3, 60),
    ('books10', 'Путешественник между строк', 'Прочитайте хотя бы одну новую страницу в 10 разных книгах', 'books', 10, 180),
    ('visits14', 'Книжный магнит', 'Заходите на сайт 14 дней подряд', 'streak', 14, 200),
    ('daily20', 'Ещё одна глава', 'Прочитайте 20 новых страниц сегодня · новое задание каждый день', 'daily', 20, 40)
  ) as a(id, title, description, metric, target, reward) loop
    progress := case item.metric when 'pages' then r.pages_read when 'streak' then r.streak_days when 'books' then books_started else daily_pages end;
    key := case when item.metric = 'daily' then 'quest:' || today::text || ':' else 'achievement:' end || item.id;
    if p_claim = item.id and progress >= item.target then
      perform public.apply_reader_reward(uid, key, item.reward, 0);
    end if;
    select exists(select 1 from public.reader_xp_ledger where owner_id=uid and reward_key=key) into earned;
    achievements := achievements || jsonb_build_array(jsonb_build_object(
      'id',item.id,'title',item.title,'description',item.description,'target',item.target,
      'progress',progress,'reward',item.reward,'earned',earned,'ready',progress >= item.target));
  end loop;
  select * into r from public.reader_stats where id = uid;
  return jsonb_build_object('xp',r.xp,'level',r.level,'streakDays',r.streak_days,'pagesRead',r.pages_read,
    'date',today,'gainedXp',r.xp-before_xp,'achievements',achievements);
end $$;
revoke all on function public.reader_journey(text,text) from public, anon;
grant execute on function public.reader_journey(text,text) to authenticated;


commit;
